describe('Order Confirmation After Successful Payment', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display order confirmation after successful payment', () => {
    // Fill in shipping and billing details
    cy.get('[data-testid="first-name-input"]').type('John');
    cy.get('[data-testid="last-name-input"]').type('Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="address-input"]').type('123 Main St');
    cy.get('[data-testid="city-input"]').type('Anytown');
    cy.get('[data-testid="zip-input"]').type('12343');
    cy.get('[data-testid="country-select"]').click();
    cy.get('[data-testid="country-option"]').click();

    // Add item to cart
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.get('[data-testid="product-quantity-input"]').clear().type('1');

    // Proceed to checkout
    cy.get('[data-testid="proceed-to-checkout-button"]').click();

    // Fill in payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvv-input"]').type('123');

    // Submit payment
    cy.get('[data-testid="place-order-button"]').click();

    // Verify order confirmation page is displayed
    cy.url().should('include', '/order-confirmation');
    cy.get('[data-testid="order-confirmation-title"]').should('be.visible').should('contain', 'Order Confirmed');
    cy.get('[data-testid="order-id"]').should('be.visible').should('have.attr', 'value');
    cy.get('[data-testid="confirmation-message"]').should('be.visible').should('contain', 'Your order has been successfully placed');
    cy.get('[data-testid="order-summary"]').should('be.visible');
  });

  it('should display payment error when card is invalid', () => {
    // Fill in shipping and billing details
    cy.get('[data-testid="first-name-input"]').type('Jane');
    cy.get('[data-testid="last-name-input"]').type('Smith');
    cy.get('[data-testid="email-input"]').type('jane@example.com');
    cy.get('[data-testid="address-input"]').type('404 Not Found');
    cy.get('[data-testid="city-input"]').type('Errorville');
    cy.get('[data-testid="zip-input"]').type('99999');
    cy.get('[data-testid="country-select"]').click();
    cy.get('[data-testid="country-option"]').click();

    // Add item to cart
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.get('[data-testid="product-quantity-input"]').clear().type('1');

    // Proceed to checkout
    cy.get('[data-testid="proceed-to-checkout-button"]').click();

    // Fill in invalid payment details
    cy.get('[data-testid="card-number-input"]').type('111111111111111'); // Invalid length
    cy.get('[data-testid="expiry-date-input"]').type('01/20');
    cy.get('[data-testid="cvv-input"]').type('12');

    // Attempt to submit payment
    cy.get('[data-testid="place-order-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="payment-error-message"]').should('be.visible');
    cy.get('[data-testid="payment-error-message"]').should('contain', 'Invalid card number');
    cy.url().should('include', '/checkout');
    cy.get('[data-testid="order-confirmation-title"]').should('not.exist');
  });
});
